# Stories from the Prophet's hadith ﷺ (Face 7.1). Draft, pending qualified review. Each is in Sahih al-Bukhari
# and/or Sahih Muslim; references checked on sunnah.com, 24 October 2026. Retold briefly in the app's own words,
# keeping only what the narration says.
S = []

S.append(dict(id="h-cave", group="hadith",
 title=("Three men trapped in a cave","গুহায় আটকে পড়া তিনজন"),
 short=("Trapped by a rock, three travellers call on Allah through the sincere deeds they had done.","একটি পাথরে আটকে পড়া তিন পথিক নিজেদের আন্তরিক আমলের উসিলায় আল্লাহকে ডাকে।"),
 parts=[("hadith","Sahih al-Bukhari 2272; Sahih Muslim 2743a",
   "The Prophet ﷺ told of three men from an earlier people who took shelter in a cave when a large rock rolled down and blocked the entrance. They agreed that only calling on Allah through their sincere good deeds could save them. The first had always given milk to his elderly parents before anyone else, and once waited all night with the cup until they woke. The second had stayed away from a sin with his cousin out of fear of Allah, though the chance was there. The third had kept a labourer's unpaid wage, invested it, and later handed over everything it had grown into. After each man's prayer the rock moved a little, and after the third it moved enough for them to walk out.",
   "নবী ﷺ পূর্ববর্তী জাতির তিন ব্যক্তির কথা বলেছেন, যারা এক গুহায় আশ্রয় নিলে একটি বড় পাথর গড়িয়ে প্রবেশমুখ বন্ধ করে দেয়। তারা একমত হয়, শুধু নিজেদের আন্তরিক সৎকাজের উসিলায় আল্লাহকে ডাকাই তাদের বাঁচাতে পারে। প্রথমজন সবসময় অন্য সবার আগে বৃদ্ধ বাবা-মাকে দুধ দিত, আর একবার তারা জাগা পর্যন্ত সারা রাত পেয়ালা হাতে অপেক্ষা করেছিল। দ্বিতীয়জন সুযোগ থাকা সত্ত্বেও আল্লাহর ভয়ে চাচাতো বোনের সঙ্গে গুনাহ থেকে বিরত থেকেছিল। তৃতীয়জন এক শ্রমিকের না নেওয়া মজুরি রেখে বিনিয়োগ করেছিল, আর পরে তা থেকে যা বেড়েছিল সব তাকে দিয়ে দিয়েছিল। প্রত্যেকের দোয়ার পর পাথর একটু সরে যায়, আর তৃতীয়জনের পর এতটা সরে যে তারা বেরিয়ে আসে।")],
 hadith=[("Sahih al-Bukhari 2272","https://sunnah.com/bukhari:2272","Sahih (in Sahih al-Bukhari)"),("Sahih Muslim 2743a","https://sunnah.com/muslim:2743a","Sahih (in Sahih Muslim)")],
 unknown=("The narration does not name the men, the place or the time; it says only that they were from people before us.",
          "বর্ণনায় ব্যক্তিদের নাম, স্থান বা সময় বলা হয়নি; শুধু বলা হয়েছে, তারা আমাদের আগের যুগের মানুষ।"),
 why=("Three ordinary kinds of goodness — care for parents, self-restraint, and honesty with money — turn out to be what saves them. Hidden, sincere deeds matter to Allah.",
      "তিনটি সাধারণ সৎগুণ — বাবা-মায়ের যত্ন, আত্মসংযম আর অর্থের ব্যাপারে সততা — শেষ পর্যন্ত তাদের রক্ষা করে। গোপন, আন্তরিক আমল আল্লাহর কাছে মূল্যবান।"),
 example=("Returning extra change a shop gave you by mistake, or paying a freelancer properly even when they forgot to invoice, are the kind of quiet honest acts this story honours.",
          "দোকান ভুল করে বেশি টাকা ফেরত দিলে তা ফিরিয়ে দেওয়া, বা কোনো ফ্রিল্যান্সার বিল পাঠাতে ভুলে গেলেও তাকে ঠিকমতো পারিশ্রমিক দেওয়া — এই কাহিনি এমন নীরব সৎ কাজকেই সম্মান দেয়।")))

S.append(dict(id="h-99", group="hadith",
 title=("The man who killed ninety-nine","নিরানব্বই জনকে হত্যাকারী"),
 short=("A man with a terrible past asks if repentance is possible, and dies on his way to change.","ভয়ংকর অতীতের এক ব্যক্তি জানতে চায় তাওবা সম্ভব কি না, আর পরিবর্তনের পথে মারা যায়।"),
 parts=[("hadith","Sahih Muslim 2766a; Sahih al-Bukhari 3470",
   "The Prophet ﷺ told of a man who had killed ninety-nine people and asked who was the most learned person on earth. He was sent to a monk and asked whether he could still repent. The monk said no, and the man killed him too, making a hundred. He then asked a scholar, who told him that nothing stands between him and repentance, and advised him to leave his land for a town where people worshipped Allah. He set out, and died halfway. The angels of mercy and the angels of punishment disagreed about him. They were told to measure the distance, and he was found nearer to the land he was heading for, so the angels of mercy took him.",
   "নবী ﷺ এক ব্যক্তির কথা বলেছেন, যে নিরানব্বই জনকে হত্যা করেছিল এবং জানতে চেয়েছিল পৃথিবীর সবচেয়ে জ্ঞানী কে। তাকে এক সংসারত্যাগী আবেদের কাছে পাঠানো হয়; সে জিজ্ঞেস করে, তার তাওবা কি এখনো সম্ভব? আবেদ বলে, না; তখন সে তাকেও হত্যা করে একশ পূর্ণ করে। তারপর সে এক আলেমকে জিজ্ঞেস করে; আলেম বলেন, তার ও তাওবার মাঝে কিছুই নেই, আর পরামর্শ দেন নিজের এলাকা ছেড়ে এমন জনপদে যেতে, যেখানে মানুষ আল্লাহর ইবাদত করে। সে রওনা দেয় এবং পথের মাঝে মারা যায়। রহমতের ফেরেশতা ও আজাবের ফেরেশতারা তাকে নিয়ে মতভেদ করে। তাদের দূরত্ব মাপতে বলা হয়, আর দেখা যায় সে যে জনপদের দিকে যাচ্ছিল তার কাছাকাছি; তাই রহমতের ফেরেশতারা তাকে নিয়ে যায়।")],
 hadith=[("Sahih Muslim 2766a","https://sunnah.com/muslim:2766a","Sahih (in Sahih Muslim)"),("Sahih al-Bukhari 3470","https://sunnah.com/bukhari:3470","Sahih (in Sahih al-Bukhari)")],
 unknown=("The narration does not name the man, the scholar, the monk or the towns. It is about Allah's mercy to a sincere repenter; it does not reduce the gravity of killing or the rights of victims, which the Qur'an and Sunnah treat with great seriousness.",
          "বর্ণনায় ব্যক্তি, আলেম, আবেদ বা জনপদের নাম নেই। এটি আন্তরিক তাওবাকারীর প্রতি আল্লাহর রহমতের কথা; হত্যার গুরুত্ব বা ক্ষতিগ্রস্তদের অধিকার, যা কুরআন ও সুন্নাহ অত্যন্ত গুরুত্ব দেয়, তা কমিয়ে দেখায় না।"),
 why=("No one should be told the door of repentance is closed. The story also shows the value of real knowledge over harsh judgement, and of changing one's surroundings when trying to change one's life.",
      "কাউকে বলা উচিত নয় যে তাওবার দরজা বন্ধ। কাহিনিটি কঠোর রায়ের চেয়ে প্রকৃত জ্ঞানের মূল্য দেখায়, আর জীবন বদলাতে চাইলে পরিবেশ বদলানোর গুরুত্বও।"),
 example=("Someone leaving a life of crime is told by a respected person, ‘There's no hope for you.’ Another tells them, ‘You can change — start by moving away from the old crowd.’ The second answer is the one in this hadith.",
          "অপরাধের জীবন ছাড়তে চাওয়া কাউকে এক সম্মানিত ব্যক্তি বলল, ‘তোমার কোনো আশা নেই।’ আরেকজন বলল, ‘তুমি বদলাতে পারো — পুরোনো সঙ্গ থেকে দূরে সরে শুরু করো।’ এই হাদিসের উত্তর দ্বিতীয়টি।")))

S.append(dict(id="h-dog", group="hadith",
 title=("The man who gave water to a thirsty dog","তৃষ্ণার্ত কুকুরকে পানি পান করানো ব্যক্তি"),
 short=("A small act of mercy to an animal is thanked by Allah.","একটি প্রাণীর প্রতি ছোট্ট দয়ার কাজ আল্লাহর কাছে মূল্য পায়।"),
 parts=[("hadith","Sahih al-Bukhari 2363; Sahih Muslim 2244",
   "The Prophet ﷺ told of a man who became very thirsty on a journey, went down into a well and drank. Coming out, he saw a dog panting and licking the mud from thirst. Realising it was suffering as he had, he went back down, filled his leather sock with water, held it in his mouth as he climbed, and gave the dog a drink. Allah thanked him for it and forgave him. The Companions asked whether there is a reward for kindness to animals, and he answered that there is a reward for kindness to every living being.",
   "নবী ﷺ এক ব্যক্তির কথা বলেছেন, যে সফরে খুব তৃষ্ণার্ত হয়ে একটি কূপে নেমে পানি পান করে। উঠে এসে দেখে, একটি কুকুর তৃষ্ণায় হাঁপাচ্ছে আর কাদা চাটছে। সে বুঝতে পারে কুকুরটি তার মতোই কষ্ট পাচ্ছে; তাই আবার নেমে চামড়ার মোজায় পানি ভরে মুখে চেপে ধরে উঠে আসে এবং কুকুরটিকে পান করায়। আল্লাহ তার এই কাজের কদর করেন এবং তাকে ক্ষমা করেন। সাহাবিরা জিজ্ঞেস করেন, পশুর প্রতি দয়ায়ও কি সওয়াব আছে? তিনি বলেন, প্রতিটি প্রাণীর প্রতি দয়ায় সওয়াব আছে।")],
 hadith=[("Sahih al-Bukhari 2363","https://sunnah.com/bukhari:2363","Sahih (in Sahih al-Bukhari)"),("Sahih Muslim 2244","https://sunnah.com/muslim:2244","Sahih (in Sahih Muslim)")],
 unknown=("The narration does not name the man, the place or the time.",
          "বর্ণনায় ব্যক্তি, স্থান বা সময়ের উল্লেখ নেই।"),
 why=("Mercy is not limited to people we know or even to people at all. Empathy — remembering how our own thirst felt — turned into action, and Allah valued it.",
      "দয়া শুধু পরিচিত মানুষ, এমনকি শুধু মানুষের মধ্যেও সীমাবদ্ধ নয়। সহমর্মিতা — নিজের তৃষ্ণার কষ্ট মনে রাখা — কাজে পরিণত হয়েছে, আর আল্লাহ তার কদর করেছেন।"),
 example=("Putting out a bowl of water for birds or stray animals on a hot day, or calling a rescue service for an injured animal, are everyday forms of the kindness this hadith praises.",
          "গরমের দিনে পাখি বা রাস্তার প্রাণীর জন্য এক বাটি পানি রাখা, বা আহত প্রাণীর জন্য উদ্ধারকারী সংস্থাকে ফোন করা — এই হাদিসে প্রশংসিত দয়ার দৈনন্দিন রূপ।")))

S.append(dict(id="h-three", group="hadith",
 title=("The leper, the bald man and the blind man","কুষ্ঠরোগী, টাকমাথা ও অন্ধ ব্যক্তি"),
 short=("Three men are healed and made rich; years later, only one remembers where it came from.","তিনজন সুস্থ ও ধনী হয়; বহু বছর পর একজনই মনে রাখে সব কোথা থেকে এসেছিল।"),
 parts=[("hadith","Sahih al-Bukhari 3464; Sahih Muslim 2964",
   "The Prophet ﷺ told of three men among the Children of Israel — one with a skin disease, one bald, and one blind — whom Allah tested by sending an angel. Each asked to be cured and was cured: good skin and colour, good hair, restored sight. Each was given a pregnant animal, and their herds grew to fill whole valleys. Later the angel came to each in the form of a poor traveller, reminding them of how they used to be and asking for help. The first two denied their past and refused. The man who had been blind said he remembered being blind and poor, and told him to take whatever he wanted. The angel told him to keep his wealth, that it had been a test, and that Allah was pleased with him and displeased with his two companions — to each of whom the angel had said that if he was lying, may Allah return him to how he was.",
   "নবী ﷺ বনি ইসরাইলের তিন ব্যক্তির কথা বলেছেন — একজন চর্মরোগী, একজন টাকমাথা, একজন অন্ধ — যাদের আল্লাহ একজন ফেরেশতা পাঠিয়ে পরীক্ষা করেন। প্রত্যেকে আরোগ্য চায় এবং আরোগ্য পায়: সুন্দর ত্বক ও রং, সুন্দর চুল, দৃষ্টিশক্তি। প্রত্যেককে একটি গর্ভবতী পশু দেওয়া হয়, আর তাদের পশুপাল বেড়ে উপত্যকা ভরে যায়। পরে ফেরেশতা দরিদ্র মুসাফিরের রূপে প্রত্যেকের কাছে আসেন, তাদের আগের অবস্থার কথা মনে করিয়ে সাহায্য চান। প্রথম দুজন অতীত অস্বীকার করে এবং ফিরিয়ে দেয়। যে অন্ধ ছিল সে বলে, সে অন্ধ ও দরিদ্র থাকার কথা মনে রেখেছে, আর যা খুশি নিয়ে যেতে বলে। ফেরেশতা তাকে সম্পদ রেখে দিতে বলেন, জানান এটি ছিল পরীক্ষা, আর আল্লাহ তার প্রতি সন্তুষ্ট এবং তার দুই সঙ্গীর প্রতি অসন্তুষ্ট — যাদের প্রত্যেককে ফেরেশতা বলেছিলেন, মিথ্যা বলে থাকলে আল্লাহ যেন তাকে আগের অবস্থায় ফিরিয়ে দেন।")],
 hadith=[("Sahih al-Bukhari 3464","https://sunnah.com/bukhari:3464","Sahih (in Sahih al-Bukhari)"),("Sahih Muslim 2964","https://sunnah.com/muslim:2964","Sahih (in Sahih Muslim)")],
 unknown=("The narration does not name the three men or say how many years passed.",
          "বর্ণনায় তিন ব্যক্তির নাম বা কত বছর কেটেছিল তা বলা হয়নি।"),
 why=("Gratitude is tested most when life is good. Remembering where we started — and helping those who are where we once were — is the answer this story praises.",
      "জীবন ভালো থাকলেই কৃতজ্ঞতার সবচেয়ে বড় পরীক্ষা হয়। কোথা থেকে শুরু করেছিলাম তা মনে রাখা — আর যারা এখন সেই অবস্থায় আছে তাদের সাহায্য করা — এই কাহিনিতে প্রশংসিত উত্তর।"),
 example=("Someone who once relied on a student hardship fund later earns well. Giving back to that same fund, instead of saying ‘I made it on my own’, is the blind man's answer in modern form.",
          "যে একসময় শিক্ষার্থীদের কষ্ট-তহবিলের ওপর নির্ভর করত, পরে সে ভালো উপার্জন করে। ‘আমি নিজেই সব করেছি’ না বলে সেই তহবিলেই ফিরিয়ে দেওয়া আধুনিক রূপে অন্ধ ব্যক্তির উত্তর।")))

S.append(dict(id="h-boy-king", group="hadith",
 title=("The boy and the king","বালক ও বাদশাহ"),
 short=("A young believer's courage leads a whole people to faith.","এক তরুণ মুমিনের সাহস পুরো এক জাতিকে ঈমানের দিকে নিয়ে আসে।"),
 parts=[("hadith","Sahih Muslim 3005",
   "The Prophet ﷺ told of a king whose ageing magician asked for a boy to train. On his way to the magician the boy met a monk and learned faith from him. Allah enabled the boy to heal the sick, and he told those he healed that it was Allah who cured them. The king had the monk and others who believed killed, and tried to kill the boy several times, but the boy was saved each time. Finally the boy told the king he could only kill him by gathering the people, and shooting an arrow while saying, ‘In the name of Allah, the Lord of the boy.’ The king did this and the boy died — and the people declared that they believed in the Lord of the boy. The king then had ditches dug and fires lit for those who would not give up their faith.",
   "নবী ﷺ এক বাদশাহর কথা বলেছেন, যার বৃদ্ধ জাদুকর একজন বালককে শেখানোর জন্য চেয়েছিল। জাদুকরের কাছে যাওয়ার পথে বালক এক সংসারত্যাগী আবেদের দেখা পায় এবং তাঁর কাছে ঈমান শেখে। আল্লাহ বালককে অসুস্থদের সুস্থ করার ক্ষমতা দেন, আর সে সুস্থ হওয়া মানুষদের বলত, আল্লাহই তাদের আরোগ্য দিয়েছেন। বাদশাহ আবেদ ও অন্য ঈমানদারদের হত্যা করায় এবং কয়েকবার বালককে হত্যার চেষ্টা করে, কিন্তু প্রতিবার সে রক্ষা পায়। শেষে বালক বাদশাহকে বলে, মানুষকে জড়ো করে ‘বালকের রব আল্লাহর নামে’ বলে তীর ছুড়লেই সে তাকে হত্যা করতে পারবে। বাদশাহ তা-ই করে আর বালক মারা যায় — আর মানুষ ঘোষণা করে, তারা বালকের রবের প্রতি ঈমান আনল। তখন বাদশাহ যারা ঈমান ছাড়বে না তাদের জন্য গর্ত খুঁড়ে আগুন জ্বালায়।")],
 hadith=[("Sahih Muslim 3005","https://sunnah.com/muslim:3005","Sahih (in Sahih Muslim)")],
 unknown=("The narration does not name the boy, the king, the monk or the land. Many commentators connect it with “the makers of the trench” in Surah al-Buruj (85:4–8), but the narration in Sahih Muslim does not state that link itself, so the app presents it only as a commentators' view.",
          "বর্ণনায় বালক, বাদশাহ, আবেদ বা দেশের নাম নেই। অনেক মুফাসসির একে সূরা আল-বুরুজের ‘কুণ্ডের অধিপতিদের’ (৮৫:৪–৮) সঙ্গে যুক্ত করেন, কিন্তু সহীহ মুসলিমের বর্ণনা নিজে এই সংযোগ বলেনি, তাই অ্যাপ এটিকে শুধু মুফাসসিরদের মত হিসেবে উল্লেখ করে।"),
 why=("The boy never claims any power for himself; every healing is credited to Allah. His goal is not survival but that people come to know their Lord — and that happens.",
      "বালক কখনো নিজের জন্য কোনো ক্ষমতা দাবি করেনি; প্রতিটি আরোগ্যকে আল্লাহর দান বলেছে। তার লক্ষ্য বেঁচে থাকা নয়, মানুষ যেন তাদের রবকে চেনে — আর তা-ই হয়।"),
 example=("A young doctor who is praised for a difficult recovery says, ‘I did my part; Allah gave the cure.’ That habit of pointing beyond oneself is the boy's legacy.",
          "কঠিন এক রোগীকে সুস্থ করে প্রশংসা পাওয়া এক তরুণ চিকিৎসক বলেন, ‘আমি আমার দায়িত্ব পালন করেছি; আরোগ্য দিয়েছেন আল্লাহ।’ নিজেকে ছাড়িয়ে আল্লাহর দিকে দেখানোর এই অভ্যাসই বালকের উত্তরাধিকার।")))

S.append(dict(id="h-juraij", group="hadith",
 title=("Juraij the worshipper","আবেদ জুরাইজ"),
 short=("A devout man ignores his mother's call, is falsely accused, and is cleared by a miracle.","এক ইবাদতগুজার মায়ের ডাকে সাড়া দেননি, মিথ্যা অপবাদে পড়েন, আর অলৌকিকভাবে নির্দোষ প্রমাণিত হন।"),
 parts=[("hadith","Sahih al-Bukhari 3436; Sahih Muslim 2550a",
   "The Prophet ﷺ said that only three spoke as babies in the cradle, and one was in the story of Juraij, a man devoted to worship. While he was praying, his mother called him; he did not answer and kept praying. She prayed that he would not die before facing a humiliating situation. Later a woman falsely claimed that her baby was his. The people tore down his place of worship and abused him. Juraij made wudu, prayed, then asked the baby who his father was, and the baby answered that it was a shepherd. The people then offered to rebuild his place of worship.",
   "নবী ﷺ বলেছেন, দোলনায় মাত্র তিনজন কথা বলেছিল, আর তাদের একজন ছিল জুরাইজ নামের এক ইবাদতগুজার ব্যক্তির ঘটনায়। তিনি নামাজে থাকা অবস্থায় তাঁর মা তাঁকে ডাকেন; তিনি সাড়া না দিয়ে নামাজ চালিয়ে যান। মা দোয়া করেন, অপমানজনক কোনো অবস্থার মুখোমুখি হওয়ার আগে যেন তাঁর মৃত্যু না হয়। পরে এক নারী মিথ্যা দাবি করে, তার শিশুটি জুরাইজের। লোকেরা তাঁর ইবাদতখানা ভেঙে ফেলে এবং তাঁকে লাঞ্ছিত করে। জুরাইজ অজু করে নামাজ পড়েন, তারপর শিশুকে জিজ্ঞেস করেন তার পিতা কে; শিশু বলে, একজন রাখাল। তখন লোকেরা তাঁর ইবাদতখানা আবার বানিয়ে দিতে চায়।")],
 hadith=[("Sahih al-Bukhari 3436","https://sunnah.com/bukhari:3436","Sahih (in Sahih al-Bukhari)"),("Sahih Muslim 2550a","https://sunnah.com/muslim:2550a","Sahih (in Sahih Muslim)")],
 unknown=("The narration does not say where or when Juraij lived. Scholars discuss what it teaches about answering parents during voluntary prayer; that discussion is a matter for scholars and is not summarised as a ruling here.",
          "বর্ণনায় জুরাইজ কোথায় বা কখন ছিলেন তা বলা নেই। নফল নামাজের সময় বাবা-মায়ের ডাকে সাড়া দেওয়া নিয়ে এ থেকে কী শিক্ষা, তা আলেমদের আলোচনার বিষয়; এখানে কোনো বিধান হিসেবে উল্লেখ করা হয়নি।"),
 why=("Two lessons sit side by side: a mother's call carries great weight, and Allah defends the innocent who turn to Him in prayer when falsely accused.",
      "দুটি শিক্ষা পাশাপাশি: মায়ের ডাকের গুরুত্ব অনেক, আর মিথ্যা অভিযোগে নামাজের মাধ্যমে আল্লাহর দিকে ফেরা নির্দোষকে আল্লাহ রক্ষা করেন।"),
 example=("Someone deep in an online course ignores repeated calls from their mother, then feels the sting of it later. This story invites us to weigh our parents' call very seriously, even against good activities.",
          "অনলাইন কোর্সে ডুবে থাকা কেউ মায়ের বারবার ফোন উপেক্ষা করে, পরে তার কষ্ট টের পায়। এই কাহিনি ভালো কাজের বিপরীতেও বাবা-মায়ের ডাককে গভীর গুরুত্ব দিতে আহ্বান জানায়।")))
